    void navItem(LinearLayout nav,String label,String glyph,String next){boolean selected=page.equals(next);LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setPadding(0,dp(2),0,dp(2));item.setBackground(ripple(R.color.surface,20));item.setMinimumHeight(dp(56));item.setContentDescription(label);item.setFocusable(true);item.setClickable(true);item.setSelected(selected);item.setOnClickListener(v->navigate(next));nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));LinearLayout pill=new LinearLayout(this);pill.setGravity(Gravity.CENTER);pill.setBackground(rounded(selected?R.color.violet:R.color.surface,20));item.addView(pill,new LinearLayout.LayoutParams(dp(64),dp(30)));pill.addView(icon(glyph,selected?R.color.primary:R.color.muted,20));TextView t=text(item,label,11);t.setGravity(Gravity.CENTER);t.setTextColor(color(selected?R.color.ink:R.color.muted));t.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);if(selected)strong(t);}
