    void swingOverview(){LinearLayout box=column();box.setPadding(dp(20),0,dp(20),dp(16));muted(box,"Each axis changes independently. Codes are positions, not degrees.",12);space(box,12);for(String cap:new String[]{Swing.VERTICAL,Swing.HORIZONTAL}){Swing.UiState state=Swing.uiState(repo.profile,repo.observed,cap,null,repo.busy,false);listrow(box,"breeze",Swing.title(cap),state.observedLabel(),true,()->{closeModal();swingChoice(cap,null);});if(!state.reason().isEmpty())muted(box,state.reason(),12);}space(box,12);muted(box,"A matching cloud code does not confirm physical movement. Position descriptions come from previous owner observations on one unit.",12);sheet("Airflow",box);}
