    void energy(){
        LinearLayout e=card(body,R.color.panel);strong(text(e,"Energy",15));muted(e,"Daily reported kWh, loaded on request. Today can be incomplete.",12);space(e,8);
        if(repo.energy==null)muted(e,"Energy hasn’t been loaded yet.",13);else if(repo.energy.length()==0)muted(e,"No energy entries returned for this period.",13);else{for(int i=0;i<repo.energy.length();i++){JSONObject entry=repo.energy.optJSONObject(i);if(entry==null)continue;String day=Data.date(entry.optString("day"));dataRow(e,day+(day.equals(java.time.LocalDate.now().toString())?" · partial":""),energyValue(Data.value(entry,"power"))+" kWh");}java.math.BigDecimal total=java.math.BigDecimal.ZERO;int numeric=0;for(int i=0;i<repo.energy.length();i++){JSONObject entry=repo.energy.optJSONObject(i);if(entry!=null)try{total=total.add(new java.math.BigDecimal(Data.value(entry,"power")));numeric++;}catch(NumberFormatException ignored){}}if(numeric>0)muted(e,energyValue(total.toPlainString())+" kWh · "+numeric+" reported entries\nMissing days are not zero-filled.",11);}
        if(repo.energyAt>0)muted(e,"Loaded "+time(repo.energyAt)+". Previous data remains visible if reload fails.",11);
        button(e,repo.energy==null?"Load recent energy":"Reload recent energy",!repo.busy,repo::loadEnergy);if(repo.energy!=null&&repo.energy.length()>0)button(e,"Export energy CSV",!repo.busy,()->export("energy"));
    }
