    void about(){String license="";try(java.io.InputStream stream=getAssets().open("lucide-LICENSE.txt")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[2048];int n;while((n=stream.read(buffer))!=-1)bytes.write(buffer,0,n);license=bytes.toString("UTF-8");}catch(java.io.IOException ignored){license="Lucide 0.468.0 · ISC license";}info("About openMirAIe","Independent MirAIe client · 0.1.0\n\nIcons: Lucide 0.468.0\n\n"+license);}
