    void rawDetails(){LinearLayout box=column();box.setPadding(dp(20),0,dp(20),dp(16));StringBuilder all=new StringBuilder("Model: "+(repo.device==null?"Not selected":repo.device.optString("modelNumber",repo.device.optString("modelId")))+"\nSource: REST mobile/status\n\n");List<String> keys=new ArrayList<>();repo.observed.keys().forEachRemaining(keys::add);Collections.sort(keys);for(String key:keys)all.append(key).append(": ").append(Data.shown(Data.value(repo.observed,key))).append('\n');TextView fields=text(box,all.toString(),14);fields.setTextIsSelectable(true);button(box,"Refresh capabilities",!repo.busy,()->{closeModal();repo.refresh(true);});button(box,"Collect redacted diagnostic snapshot",!repo.busy,()->{closeModal();repo.diagnostic();});sheet("Device details",box);}
