    void signout(){discard(()->confirm("Sign out?","The saved session will be removed. Local reading snapshots remain on this phone.",()->{repo.signOut();}));}
    void discard(Runnable action){if(!repo.busy)action.run();}
    void confirm(String title,String message,Runnable action){modal=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Continue",(d,w)->{if(!repo.busy)action.run();}).show();}
    void info(String title,String message){modal=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Close",null).show();}
    void sheet(String title,LinearLayout content){if(temperatureDial!=null)temperatureDial.cancelInteraction();modalLauncher=getCurrentFocus();LinearLayout all=column();all.setPadding(0,dp(10),0,0);View handle=new View(this);handle.setBackground(rounded(R.color.line,3));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(30),dp(4));hp.gravity=Gravity.CENTER_HORIZONTAL;all.addView(handle,hp);LinearLayout head=row(all);head.setPadding(dp(20),dp(6),dp(10),dp(8));TextView heading=text(head,title,24);strong(heading);weighted(heading);iconButton(head,"close","Close dialog",true,this::closeModal);ScrollView scroller=new ScrollView(this);scroller.setFillViewport(false);scroller.addView(content);all.addView(scroller,new LinearLayout.LayoutParams(-1,-2));modal=new AlertDialog.Builder(this).setView(all).create();modal.show();bottom(modal);modal.setOnDismissListener(d->{restoreModalFocus();});if(android.animation.ValueAnimator.areAnimatorsEnabled()){all.setTranslationY(dp(24));all.setAlpha(0);all.animate().translationY(0).alpha(1).setDuration(240).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();}}
    void bottom(AlertDialog d){Window window=d.getWindow();if(window!=null){window.setBackgroundDrawable(rounded(R.color.panel,32));window.setGravity(Gravity.BOTTOM);window.setLayout(-1,-2);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams params=window.getAttributes();params.dimAmount=.28f;window.setAttributes(params);}for(int which:new int[]{AlertDialog.BUTTON_POSITIVE,AlertDialog.BUTTON_NEGATIVE}){Button b=d.getButton(which);if(b!=null){b.setAllCaps(false);b.setTextColor(color(R.color.primary));b.setMinHeight(dp(48));}}}
    void restoreModalFocus(){if(modalLauncher!=null&&modalLauncher.isAttachedToWindow())modalLauncher.requestFocus();modalLauncher=null;}
    void closeModal(){if(modal!=null)modal.dismiss();}
    void export(String kind){exportKind=kind;exportDevice=repo.device.optString("deviceId");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"openmiraie-"+kind+"-"+java.time.LocalDate.now()+".csv");startActivityForResult(i,40);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=40||result!=RESULT_OK||data==null||data.getData()==null)return;
        if(!repo.signed||repo.device==null||!repo.device.optString("deviceId").equals(exportDevice)){info("Export cancelled","The selected account or AC changed. Export again from the intended device.");return;}
        String kind=exportKind,device=exportDevice;android.net.Uri destination=data.getData();repo.task("Writing CSV…",()->{String csv=kind.equals("energy")?Data.energyCsv(repo.energy):repo.snapshots.csv(device);try(OutputStream out=getContentResolver().openOutputStream(destination,"wt")){if(out==null)throw new IOException();out.write(csv.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.flush();}repo.notice="CSV saved.";});
    }
    static Double parse(String s){try{double d=Double.parseDouble(s);return Double.isFinite(d)?d:null;}catch(Exception e){return null;}}
    static String number(double n){return java.math.BigDecimal.valueOf(n).stripTrailingZeros().toPlainString();}
    @android.annotation.SuppressLint("SimpleDateFormat")
    static String time(long ms){return java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(new Date(ms));}
